class SafeCounter { int value=0; ReentrantReadWriteLock lock = new ReentrantReadWriteLock();
    void increment() { lock.writeLock().lock(); try { value++; } finally { lock.writeLock().unlock(); } }
    int getValue() { lock.readLock().lock(); try { return value; } finally { lock.readLock().unlock(); } }
}
SafeCounter counter = new SafeCounter();
// 4 watki-pisarzy x 1000 increment(), 4 watki-czytelnikow sprawdzajacych ze wartosc nie maleje
