void shutdownAndWait(ExecutorService pool) throws InterruptedException {
    pool.shutdown();
    if (!pool.awaitTermination(5, TimeUnit.SECONDS)) pool.shutdownNow();
}
ExecutorService pool = Executors.newFixedThreadPool(9);
// 3 zadania writeLock, 6 zadan readLock
