ReentrantReadWriteLock rwLock = new ReentrantReadWriteLock();
String[] value = {null};
void writeAndDowngrade(String nowaWartosc) {
    rwLock.writeLock().lock();
    try {
        value[0] = nowaWartosc;
        rwLock.readLock().lock(); // zdobywamy readLock, WCIAZ trzymajac writeLock - bezpieczne 'obnizenie'
    } finally { rwLock.writeLock().unlock(); }
    try { System.out.println("wlasnie zapisano i odczytano: " + value[0]); }
    finally { rwLock.readLock().unlock(); }
}
// 2 watki-pisarze wywolujace writeAndDowngrade() po 5 razy kazdy

Map<Integer, List<Integer>> graf = new HashMap<>();
ReentrantReadWriteLock lock = new ReentrantReadWriteLock();
void dodajKrawedz(int a, int b) { lock.writeLock().lock(); try { graf.computeIfAbsent(a, k -> new ArrayList<>()).add(b); } finally { lock.writeLock().unlock(); } }
int liczKrawedzie() { lock.readLock().lock(); try { return graf.values().stream().mapToInt(List::size).sum(); } finally { lock.readLock().unlock(); } }
// 3 watki-pisarzy x 10 dodajKrawedz(), 6 watkow-czytelnikow x 10 liczKrawedzie() po zakonczeniu pisarzy
System.out.println(liczKrawedzie() == 30);

class VersionedCache {
    String value; long timestamp; int version = 0;
    ReentrantReadWriteLock lock = new ReentrantReadWriteLock();
    void set(String v) { lock.writeLock().lock(); try { value=v; timestamp=System.currentTimeMillis(); version++; } finally { lock.writeLock().unlock(); } }
    int[] readConsistent() { lock.readLock().lock(); try { return new int[]{version}; } finally { lock.readLock().unlock(); } } // uproszczenie: w praktyce zwroc tez value+timestamp razem
}
// watek aktualizujacy: 5x set() co 300ms; 8 watkow czytajacych: po 10x readConsistent(), zweryfikuj spojnosc

// (a) synchronized - wszystkie operacje na 1 monitorze
// (b) ReentrantLock - wszystkie operacje na 1 blokadzie
// (c) ReentrantReadWriteLock - odczyty na readLock, zapisy na writeLock
// dla kazdego: 100 watkow x 20 operacji (90% odczyt/10% zapis), zmierz laczny czas
System.out.println(String.format("%-15s %s", "wariant", "czas(ms)"));
